  let out = panelHeader(x,y,'A','Global DALY burden structurally flips','Share of global DALYs by category; labels show percent of annual total');
  const barX=x+70, barY=y+80, barW=520, barH=50;
  [1990,2024].forEach((year,i)=>{
    const rows = data.filter(d=>d.year===year);
    const total = rows.reduce((a,d)=>a+d.dalys_millions,0);
    const yy = barY + i*92;
    out += text(x, yy+33, year, 30, 800, colors.ink);
    out += stackedBar(barX, yy, barW, barH, rows.map(d=>({category:d.category,value:d.dalys_millions})), total);
    out += text(barX+barW+18, yy+20, `${fmt(total)}`, 22, 800, colors.ink);
    out += text(barX+barW+18, yy+43, 'million DALYs', 14, 500, colors.muted);
  });
  out += line(barX, barY+142, barX+barW, barY+142, '#BEB6AA', 1, 'stroke-dasharray="3 5"');
  out += text(barX, barY+193, '1990: communicable conditions are the largest block', 18, 700, colors.Communicable);
  out += text(barX, barY+219, '2024: NCDs dominate the global burden', 18, 700, colors.NCD);
  return out;
}

function incomePanel() {
  const x=820, y=218, w=900;
  const data = source.daly_by_income_group.data;
  let out = panelHeader(x,y,'B','Income groups remain at different stages of transition','100% stacked bars: percentage of total DALYs within each income group');
  const groups = ['Low income','Lower-middle income','Upper-middle income','High income'];
  const barX = x+210, barW = 570, barH = 24;
  const startY = y+82;
  const rowGap = 74;
  out += text(barX, y+58, '1990', 17, 800, colors.muted);
  out += text(barX, y+90, '', 1);
  [0,25,50,75,100].forEach(t=>{
    const tx=barX + barW*t/100;
    out += line(tx,startY-18,tx,startY+groups.length*rowGap+34,'#ECE4DA',1);
    out += text(tx,startY-28,`${t}%`,13,600,colors.muted,'middle');
  });
  groups.forEach((group,gi)=>{
    const yy = startY + gi*rowGap;
    out += multiText(x, yy+8, group, 18, 19, 700, colors.ink, 'start', 21);
    [1990,2024].forEach((year,yi)=>{
      const row = data.find(d=>d.year===year && d.income_group===group);
      const by = yy + yi*31;
      out += text(barX-50, by+18, String(year), 14, 700, yi===0?colors.muted:colors.ink, 'end');
      out += stackedBar(barX, by, barW, barH, [
        {category:'Communicable', value: row.communicable_pct, label: row.communicable_pct >= 18 ? pct(row.communicable_pct) : ''},
        {category:'NCD', value: row.ncd_pct, label: row.ncd_pct >= 18 ? pct(row.ncd_pct) : ''},
        {category:'Injury', value: row.injury_pct, label: row.injury_pct >= 10 ? pct(row.injury_pct) : ''}
      ], 100, true);
    });
  });
  out += rect(x+2, startY-12, 7, 64, colors.Communicable, 'none', 3);
  out += rect(x+2, startY+rowGap*3-12, 7, 64, colors.NCD, 'none', 3);
  out += text(barX+barW-6, startY+groups.length*rowGap+58, 'Low-income countries still carry 52.8% communicable DALYs; high-income countries are 87.8% NCD in 2024.', 18, 700, colors.ink, 'end');
  return out;
}

function rankPanel() {
  const x=70, y=600, w=1655, h=650;
  const data = source.top10_daly_causes.data;
  const d1990 = data.filter(d=>d.year===1990);
  const d2024 = data.filter(d=>d.year===2024);
  const map90 = new Map(d1990.map(d=>[d.cause,d]));
  const map24 = new Map(d2024.map(d=>[d.cause,d]));
  const causes = Array.from(new Set([...d1990.map(d=>d.cause), ...d2024.map(d=>d.cause)]));
  const categoryFor = cause => (map24.get(cause) || map90.get(cause)).category;
  const x1=x+390, x2=x+1195, top=y+105, rowH=43, bottom=top+10*rowH;
  let out = panelHeader(x,y,'C','Top-cause ranks: chronic diseases rise as infections recede','Bump chart of rank among top 10 global DALY causes; values beside labels are millions of DALYs');
  out += text(x1, y+76, '1990 rank', 21, 800, colors.ink, 'middle');
  out += text(x2, y+76, '2024 rank', 21, 800, colors.ink, 'middle');
  out += line(x1, top-20, x1, bottom+12, '#BEB6AA', 2);
  out += line(x2, top-20, x2, bottom+12, '#BEB6AA', 2);
  for (let r=1;r<=10;r++) {
    const yy=top+(r-1)*rowH;
    out += line(x1-10, yy, x2+10, yy, '#EFE8DE', 1);
    out += text(x1-22, yy+6, r, 15, 800, colors.muted, 'end');
    out += text(x2+22, yy+6, r, 15, 800, colors.muted, 'start');
  }
  const notY=top+10*rowH+38;
  out += line(x1-10, notY, x2+10, notY, '#E2D8CB', 1, 'stroke-dasharray="5 6"');
  out += text((x1+x2)/2, notY+6, 'not in top 10', 15, 700, colors.muted, 'middle');
  const getY = (rank) => rank ? top+(rank-1)*rowH : notY;
  causes.forEach(cause=>{
    const a=map90.get(cause), b=map24.get(cause);
    const yA=getY(a?.rank), yB=getY(b?.rank);
    const cat=categoryFor(cause);
    const width = (cause==='Ischemic heart disease' || cause==='Lower respiratory infections') ? 5.2 : 3.2;
    const opacity = (a && b) ? 0.88 : 0.42;
    out += `<path d="M ${x1} ${yA} C ${x1+255} ${yA}, ${x2-255} ${yB}, ${x2} ${yB}" fill="none" stroke="${colors[cat]}" stroke-width="${width}" opacity="${opacity}" stroke-linecap="round"/>`;
    out += `<circle cx="${x1}" cy="${yA}" r="${a&&b?7:5}" fill="${colors[cat]}" opacity="${opacity}"/>`;
    out += `<circle cx="${x2}" cy="${yB}" r="${a&&b?7:5}" fill="${colors[cat]}" opacity="${opacity}"/>`;
  });
  d1990.forEach(d=>{
    const yy=getY(d.rank);
    out += text(x1-42, yy-4, d.cause, 18, (d.cause==='Lower respiratory infections'||d.cause==='Ischemic heart disease')?800:600, colors.ink, 'end');
    out += text(x1-42, yy+17, `${fmt(d.dalys_millions)}m`, 13, 600, colors.muted, 'end');
  });
  d2024.forEach(d=>{
    const yy=getY(d.rank);
    out += text(x2+42, yy-4, d.cause, 18, (d.cause==='Lower respiratory infections'||d.cause==='Ischemic heart disease')?800:600, colors.ink, 'start');
    out += text(x2+42, yy+17, `${fmt(d.dalys_millions)}m`, 13, 600, colors.muted, 'start');
  });
  // label causes that fell out or entered top 10
  ['Diarrheal diseases','Malaria','Tuberculosis','Measles'].forEach((c,i)=>{
    const d=map90.get(c); const yy=notY-46+i*18;
    out += text(x1-42, yy, `${c} ↓ out`, 13, 700, colors.Communicable, 'end');
  });
  ['Diabetes mellitus','Low back pain','Depressive disorders','Lung cancer'].forEach((c,i)=>{
    const yy=notY-46+i*18;
    out += text(x2+42, yy, `new: ${c}`, 13, 700, colors.NCD, 'start');
  });
  out += `<path d="M ${x1+95} ${getY(4)-18} C ${x1+300} ${getY(4)-78}, ${x2-255} ${getY(1)-48}, ${x2-95} ${getY(1)-18}" fill="none" stroke="#17212B" stroke-width="1.3" stroke-dasharray="4 5" opacity="0.8"/>`;
  out += text((x1+x2)/2, y+130, 'Ischemic heart disease rises 4 → 1', 22, 800, colors.NCD, 'middle');
  out += text((x1+x2)/2, y+170, 'Lower respiratory infections fall 1 → 6', 22, 800, colors.Communicable, 'middle');
  out += text(x, y+h-22, 'Source: provided benchmark datasets. DALYs = disability-adjusted life years; communicable includes maternal, neonatal, and nutritional conditions.', 16, 500, colors.muted);
  return out;
}

